// Joins every file in supabase/migrations into one file, supabase/run_all.sql,
// so the owner can paste it once into the Supabase SQL Editor.
// Run with: npm run db:bundle   (re-run whenever a migration is added)
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const dir = join(import.meta.dirname, '..', 'supabase', 'migrations')
const files = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort()

let out = `-- Alemiya Academy: all database migrations in one file.
-- GENERATED by "npm run db:bundle". Do not edit; edit the files in supabase/migrations instead.
-- Run this ONCE on a new, empty Supabase project (SQL Editor > New query > paste > Run).
-- Running it twice fails with "already exists", which is safe: nothing is changed.
-- Files included: ${files.join(', ')}
`
for (const f of files) {
  out += `\n-- ======================================================================\n-- ${f}\n-- ======================================================================\n`
  out += readFileSync(join(dir, f), 'utf8')
}
writeFileSync(join(import.meta.dirname, '..', 'supabase', 'run_all.sql'), out)
console.log(`Wrote supabase/run_all.sql from ${files.length} migration files`)
